import {renderView,section,form,field,textInput,selectInput,button,list} from '../ui/view.js';import {ArtService} from '../services/art-service.js';import {BookService} from './literary-services-book-service.js';import {createArtState,addLayer} from './literary-engines-art-state.js';import {el,formDataObject} from './literary-core-dom.js';import {notify} from './literary-core-notifications.js';
let state=createArtState(),current=null,ctx=null,drawing=false,last=null;
function drawCanvas(){const canvas=document.querySelector('#art-canvas');if(!canvas)return;canvas.width=state.canvas.width;canvas.height=state.canvas.height;ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);const bg=state.background||{};if(bg.type==='color'&&bg.value){ctx.save();ctx.fillStyle=bg.value;ctx.fillRect(0,0,canvas.width,canvas.height);ctx.restore();}for(const layer of state.layers){if(layer.visible===false||layer.type!=='stroke-layer')continue;ctx.save();ctx.globalAlpha=Number(layer.opacity??1);for(const stroke of layer.content?.strokes||[]){ctx.beginPath();ctx.lineWidth=stroke.size||8;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=stroke.color||'#000';stroke.points?.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.stroke();}ctx.restore();}}
function activeStrokeLayer(){let l=state.layers.findLast?.(x=>x.type==='stroke-layer'&&!x.locked)||[...state.layers].reverse().find(x=>x.type==='stroke-layer'&&!x.locked);if(!l){state=addLayer(state,{name:'Paint',type:'stroke-layer',content:{strokes:[]}});l=state.layers[state.layers.length-1];}return l;}
function pointer(e){const c=e.currentTarget,r=c.getBoundingClientRect();return {x:(e.clientX-r.left)*(c.width/r.width),y:(e.clientY-r.top)*(c.height/r.height)};}
function installDrawing(){const c=document.querySelector('#art-canvas');c.addEventListener('pointerdown',e=>{drawing=true;c.setPointerCapture(e.pointerId);last=pointer(e);const layer=activeStrokeLayer();layer.content ||= {strokes:[]};layer.content.strokes.push({color:state.palette.active||'#000000',size:state.toolSettings.brush?.size||8,points:[last]});drawCanvas();});c.addEventListener('pointermove',e=>{if(!drawing)return;const p=pointer(e),layer=activeStrokeLayer(),stroke=layer.content.strokes.at(-1);stroke.points.push(p);last=p;drawCanvas();});const up=()=>{drawing=false;last=null;};c.addEventListener('pointerup',up);c.addEventListener('pointercancel',up);}
async function saveArt(){const payload={id:current?.id,name:document.querySelector('#art-name')?.value||'Cover Art',width:state.canvas.width,height:state.canvas.height,dpi:state.canvas.dpi,canvas:state.canvas,layers:state.layers,palette:state.palette,toolSettings:state.toolSettings,background:state.background};const r=await ArtService.save(payload);current=r.art;notify('Art project saved.');}
async function openArt(art){const r=await ArtService.get(art.id);current=r.art;state={canvas:r.art.canvas||{width:r.art.width,height:r.art.height,dpi:r.art.dpi},layers:r.art.layers||[],palette:r.art.palette||{active:'#000000'},toolSettings:r.art.toolSettings||{brush:{size:8}},background:r.art.background||{type:'transparent'}};document.querySelector('#art-name').value=current.name||'Cover Art';drawCanvas();}
export async function artStudioView(){const r=await ArtService.list(),projects=r.projects||r.artProjects||[],body=el('div',{class:'art-studio-workspace'});const controls=section('Canvas controls');controls.append(field('Project name',el('input',{id:'art-name',value:'Cover Art'})));controls.append(field('Brush color',el('input',{id:'art-color',type:'color',value:'#000000',onInput:e=>state.palette.active=e.target.value})));controls.append(field('Brush size',el('input',{id:'art-size',type:'range',min:1,max:100,value:8,onInput:e=>{state.toolSettings.brush ||= {};state.toolSettings.brush.size=Number(e.target.value);}})));controls.append(button('New transparent canvas',()=>{state=createArtState();current=null;document.querySelector('#art-name').value='Cover Art';drawCanvas();}));controls.append(button('Add paint layer',()=>{state=addLayer(state,{name:`Layer ${state.layers.length+1}`,type:'stroke-layer',content:{strokes:[]}});drawCanvas();}));controls.append(button('Save project',saveArt));controls.append(button('AI generate image',async()=>{if(!current){await saveArt();}const prompt=window.prompt('Describe the image to create.');if(!prompt)return;await ArtService.generate(current.id,{prompt,width:state.canvas.width,height:state.canvas.height});notify('AI image generation completed. Generated assets were saved to this art project.');}));
 const canvas=el('canvas',{id:'art-canvas',width:state.canvas.width,height:state.canvas.height,tabIndex:0,'aria-label':'Art Studio canvas'});body.append(controls,section('Canvas',[canvas]),section('Saved art projects',[list(projects,p=>button(p.name||'Art Project',()=>openArt(p)),{empty:'No art projects saved yet.'})]));renderView('Art Studio',{description:'Create and refine cover art with canvas, layers, painting, transforms, selections, color tools, uploaded assets, and backend AI generation.',body});installDrawing();drawCanvas();}
